import numpy as np
from math import erf, erfc, exp, sin, cos, sqrt, pi

def ewald_field(lat, charges, positions, point, alpha, nT=6, nG=30):
    a=np.diag(lat); vol=np.linalg.det(lat)
    E=np.zeros(3)
    # real space
    for qi,pos in zip(charges,positions):
        for i in range(-nT,nT+1):
          for j in range(-nT,nT+1):
           for k in range(-nT,nT+1):
            T=lat@np.array([i,j,k])
            r=point-(pos+T); rr=np.linalg.norm(r)
            if rr<1e-12: continue
            E += qi*r*(erfc(alpha*rr)/rr**3 + 2*alpha*exp(-(alpha*rr)**2)/sqrt(pi)/rr**2)
    # reciprocal (standard) excluding G=0
    fac=4*pi/vol
    for i in range(-nG,nG+1):
      for j in range(-nG,nG+1):
       for k in range(-nG,nG+1):
        if i==0 and j==0 and k==0: continue
        G=2*pi*np.array([i,j,k])/a; g2=G@G
        rho=sum(qi*exp(1j*(G@pos)) for qi,pos in zip(charges,positions))
        E += (fac/g2*G*np.imag(np.exp(1j*(G@point))*rho)*exp(-0.25*g2/(alpha*alpha)))
        # real part: sum over +- already handled by full set; imag part gives sin
    return E

# use code A_sd with corrected coefficient: for a single charge at pos=0, field at point r = sum_G G sin(gv) expk + direct erfc field
def code_field(lat, charge, pos, point, alpha, nT=6, nG=30):
