    E=np.zeros(3)
    for i in range(-nT,nT+1):
      for j in range(-nT,nT+1):
       for k in range(-nT,nT+1):
        T=lat@np.array([i,j,k]); r=point-(pos+T); rr=np.linalg.norm(r)
        if rr<1e-12: continue
        E += charge*r*(erfc(alpha*rr)/rr**3 + 2*alpha*exp(-(alpha*rr)**2)/sqrt(pi)/rr**2)
    for i in range(-nG,nG+1):
      for j in range(-nG,nG+1):
       for k in range(-nG,nG+1):
        if i==0 and j==0 and k==0: continue
        G=2*pi*np.array([i,j,k])/a; g2=G@G; gv=G@(point-pos)
        expk=fac*exp(-0.25*g2/(alpha*alpha))/g2
        E += charge*G*sin(gv)*expk
    return E
lat=np.eye(3)*10.0
point=np.array([0.2,0.4,-0.3]); pos=np.array([0.1,-0.2,0.05])
